-- 0056: أدلة المنشأة — دليل التشغيل والصيانة (للمرافق والصيانة) ودليل مستخدمي المنشأة، يُولَّدان لكل منشأة عند التسليم (G-04)
-- القوالب في manual_templates (يحررها المسؤول، والبذرة لا تستبدل تعديلاته)، ودليل كل منشأة في facility_manuals (بيانات خاصة + سجل إصدارات).
create table if not exists public.manual_templates (
  code text primary key, title text not null, audience text not null default '', sections jsonb not null default '[]'::jsonb,
  version text not null default '1.0', updated_at timestamptz not null default now());
create table if not exists public.facility_manuals (
  id bigserial primary key,
  kind text not null references public.manual_templates(code),
  facility_id bigint not null references public.facilities(id),
  project_id uuid references public.projects(id) on delete set null,
  title text not null default '',
  status text not null default 'draft' check (status in ('draft','issued')),
  version int not null default 0,
  data jsonb not null default '{}'::jsonb,
  log jsonb not null default '[]'::jsonb,
  issued_at timestamptz, issued_by text,
  created_by uuid default auth.uid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists facility_manuals_fac on public.facility_manuals(facility_id);
alter table public.manual_templates enable row level security;
alter table public.facility_manuals enable row level security;
drop policy if exists p_read on public.manual_templates; create policy p_read on public.manual_templates for select using (public.is_active_user());
drop policy if exists p_admin on public.manual_templates; create policy p_admin on public.manual_templates for all using (public.is_admin()) with check (public.is_admin());
drop policy if exists p_read on public.facility_manuals; create policy p_read on public.facility_manuals for select using (public.is_active_user());
drop policy if exists p_write on public.facility_manuals; create policy p_write on public.facility_manuals for insert with check (public.is_admin() or public.can_edit() or public.my_unit() in ('PRJ','FAC','MNT','SAF'));
drop policy if exists p_upd on public.facility_manuals; create policy p_upd on public.facility_manuals for update using (public.is_admin() or public.can_edit() or public.my_unit() in ('PRJ','FAC','MNT','SAF')) with check (public.is_admin() or public.can_edit() or public.my_unit() in ('PRJ','FAC','MNT','SAF'));
drop policy if exists p_del on public.facility_manuals; create policy p_del on public.facility_manuals for delete using (public.is_admin());
grant select, insert, update, delete on public.manual_templates, public.facility_manuals to authenticated;
grant usage, select on sequence public.facility_manuals_id_seq to authenticated;

insert into public.manual_templates(code,title,audience,sections) values ('om','دليل التشغيل والصيانة','فرق المرافق والصيانة والأمن والسلامة وتقنية المعلومات والصيانة الطبية','[{"key": "about", "title": "عن هذا الدليل", "body": "هذا الدليل هو المرجع الفني لتشغيل {facility} وصيانتها بعد استلامها من قسم المشاريع، ويُسلَّم ضمن ملف التسليم في إجراء استلام المشروع وتسليمه للتشغيل (G-04)، ولا يُعد التسليم مكتملاً بدونه (R-42).\n## لمن هذا الدليل\n- المرافق: سجل المواقع وحالة الغرف وتنسيق الدخول (F-03).\n- الصيانة: الأنظمة وخرائط الإغلاق والصيانة الوقائية والطوارئ (G-05، G-06، G-11).\n- الأمن والسلامة: أنظمة الحريق ومخططات الإخلاء والمواد الخطرة (H-01، H-02، H-04).\n- تقنية المعلومات والصيانة الطبية: الأنظمة التقنية ومواقع الأجهزة الطبية (T-02، G-07).\n## كيف يُستخدم ويُحدَّث\n- كل جدول في هذا الدليل يُسحب من المنصة مباشرة (المواقع، الأصول، الضمانات، خطط الصيانة)، فيبقى محدثاً كلما حُدّثت المنصة.\n- أي تعديل في المساحات أو الأنظمة بعد التسليم يُحدَّث في الدليل ضمن إجراء إدارة التغيير في المساحات (G-12)، ويُرفع رقم الإصدار.\n- يُراجَع الدليل سنوياً ضمن التقويم السنوي (K-30)، ويعتمده مدير الإدارة.\n> المرجعية: معايير سباهي للمنشآت الصحية — فصل إدارة المرافق والسلامة، وخطة أنظمة المرافق (PL-06)."}, {"key": "card", "title": "بطاقة المنشأة والمشروع", "auto": "project", "body": "بيانات المنشأة والمشروع الذي سُلّمت بموجبه، كما هي مسجلة في المنصة."}, {"key": "contacts", "title": "جهات الاتصال", "rows": "contacts", "cols": [["role", "الجهة / الدور"], ["name", "الاسم"], ["phone", "الهاتف"], ["note", "متى يُتصل به"]], "body": "من يُتصل به في التشغيل اليومي والطوارئ وفترة الضمان. في الطوارئ يُتصل بالصيانة مباشرة ثم يُسجَّل البلاغ (R-09).", "defaults": [["غرفة الصيانة (طوارئ على مدار الساعة)", "", "", "أي عطل يهدد السلامة أو الخدمة"], ["الأمن والسلامة", "", "", "حريق، دخان، تعطيل أنظمة الحريق، حادث"], ["المرافق", "", "", "إغلاق غرفة، نقل أو تعديل مساحة"], ["تقنية المعلومات", "", "", "الشبكة والأنظمة"], ["الصيانة الطبية", "", "", "أعطال الأجهزة الطبية"], ["مقاول المشروع (فترة الضمان)", "", "", "عيوب الضمان — عبر قسم المشاريع"], ["مهندس المشروع", "", "", "ملف التسليم والضمان"]]}, {"key": "spaces", "title": "الفراغات والمواقع وترميز الغرف", "auto": "rooms", "body": "كل غرفة وفراغ في المنشأة له رمز ثابت مثبت على لوحة الغرفة ومسجل في المنصة. كل بلاغ أو عمل يُسجَّل على رمز الغرفة (R-16)، والإغلاق والفتح يتمان بإجراء موثق (F-01، R-11).\n- الفراغات الحرجة معلَّمة في الجدول، ولا تُغلق إلا باعتماد مدير الإدارة (R-12).\n- أي تغيير في استخدام فراغ أو رمزه يمر بإجراء إدارة التغيير (G-12) ويُحدَّث هنا."}, {"key": "systems", "title": "الأنظمة المسلَّمة وخرائط الإغلاق", "rows": "systems", "cols": [["system", "النظام"], ["desc", "الوصف والسعة"], ["where", "موقع المعدات واللوحات"], ["shutoff", "نقطة الإغلاق / العزل"], ["serves", "ما يخدمه"], ["note", "ملاحظات التشغيل"]], "body": "جدول الأنظمة التي سُلّمت في هذه المنشأة. أهم عمود فيه «نقطة الإغلاق»: الفني المناوب يجب أن يعرف أين يقطع الكهرباء أو المياه أو الغاز عن أي منطقة دون بحث (PL-06).\n! أي عمل على هذه الأنظمة يحتاج تصريح عمل وعزلاً آمناً (M-01)، وأي إيقاف مخطط يحتاج إشعاراً وبديلاً (M-02، R-15).", "defaults": [["الكهرباء — التغذية الرئيسية واللوحات", "", "", "", "", ""], ["المولد الاحتياطي والتحويل الآلي", "", "", "", "الأحمال الأساسية", "اختبار شهري تحت الحمل (K-01)"], ["التكييف والتهوية", "", "", "", "", "الضغط في المناطق الخاصة"], ["المياه والصرف", "", "", "", "", "خطة إدارة المياه (K-10)"], ["الغازات الطبية والتفريغ", "", "", "", "", "NFPA 99"], ["الإنذار من الحريق", "", "", "", "", "NFPA 72"], ["الإطفاء (رشاشات، صناديق، طفايات)", "", "", "", "", "NFPA 25"], ["المصاعد", "", "", "", "", ""], ["التيار الخفيف والشبكات", "", "", "", "", "تقنية المعلومات (T-02)"], ["أنظمة الدخول والكاميرات", "", "", "", "", "(H-05)"]]}, {"key": "assets", "title": "سجل الأصول", "auto": "assets", "body": "الأصول المسجلة للمنشأة في المنصة، وتُدرج أصول المشروع الجديدة خلال أسبوع من الاستلام (G-04). لكل أصل رقم ثابت ومستوى أهمية، وتُربط به البلاغات وأوامر الصيانة فيتكون تاريخه كاملاً."}, {"key": "warranty", "title": "الضمانات", "auto": "warranty", "rows": "warranties", "cols": [["item", "البند / النظام"], ["supplier", "المورد / الوكيل"], ["until", "ينتهي في"], ["contact", "التواصل"], ["note", "شروط مهمة"]], "body": "## خلال فترة الضمان\n- أي عيب يُكتشف يُبلَّغ عنه من الصيانة في المنصة، ويطالب به قسم المشاريع المقاول (R-07، P-14).\n- لا تُجرى إصلاحات داخلية على بند ضمان قبل التنسيق مع قسم المشاريع حتى لا يسقط الضمان.\n- قبل انتهاء الضمان بثلاثة أشهر: جولة فحص مشتركة وقائمة ملاحظات تُسلّم للمقاول (K-25).\nالجدول الأول من سجل الأصول في المنصة، والثاني لخطابات الضمان الخاصة بالمشروع."}, {"key": "ppm", "title": "الصيانة الوقائية المخططة", "auto": "plans", "body": "خطط الصيانة الدورية المسجلة للمنشأة في المنصة؛ كل خطة تولّد أمر العمل تلقائياً قبل موعده، ويُغلق الأمر بقائمة التحقق والنتيجة (G-06). المستهدف إنجاز 90٪ على الأقل في شهرها.\n## الحد الأدنى الذي يجب أن تغطيه الخطط\n- المولدات: فحص أسبوعي، واختبار شهري تحت الحمل (K-01).\n- مضخات الحريق: تشغيل أسبوعي أو شهري، واختبار تدفق سنوي (K-02، K-03).\n- الرشاشات: فحص ربع سنوي (K-04)، والإنذار: اختبار شامل سنوي (K-05).\n- الغازات الطبية: اختبار سنوي (K-06)، والمصاعد: شهادة سلامة سنوية (K-07).\n- التكييف: تنظيف المرشحات بحسب الصانع، وجاهزية الصيف (K-08).\n- الأسطح والمصارف: قبل موسم الأمطار (K-09)، وإدارة المياه ربع سنوياً (K-10)."}, {"key": "daily", "title": "التشغيل اليومي والجولات", "body": "## جولة الفني اليومية\n- لوحات الكهرباء الرئيسية: لا إنذارات، لا حرارة أو رائحة غير طبيعية.\n- المولد: مستوى الوقود، وحالة البطاريات وشاحنها، ووضع المفتاح على «آلي».\n- غرف التكييف: تشغيل الوحدات، تسرب المياه، أصوات غير طبيعية.\n- لوحة الإنذار من الحريق: «طبيعي» بلا أعطال أو تعطيلات غير مسجلة (H-01).\n- الغازات الطبية: ضغوط المصدر وإنذارات المناطق.\n- المصاعد: تعمل وأزرار الطوارئ والاتصال سليمة.\n## الجولات الدورية\n- جولات بيئة الرعاية بحسب التقويم (F-02، K-16)، وتُغلق ملاحظاتها في مهلتها.\n- كل ملاحظة تُسجَّل بلاغاً على رمز الغرفة أو الأصل في المنصة، لا شفهياً."}, {"key": "materials", "title": "التشطيبات والخامات والعناية بها", "rows": "materials", "cols": [["item", "الخامة / العنصر"], ["code", "الرمز / المواصفة"], ["where", "مواقعها"], ["care", "التنظيف والعناية"], ["source", "مصدر الاستبدال"]], "body": "الخامات المعتمدة في هوية التجمع لها رموز ثابتة، والاستبدال يكون بالرمز نفسه لا بالأقرب شكلاً، حتى تبقى المنشأة على هويتها.\n- لا تُستخدم مواد تنظيف تتلف الفينيل أو حماية الجدران؛ يُلتزم بتعليمات الصانع.\n- لا تُثقب الجدران ولا تُثبت لوحات أو رفوف إلا بطلب عبر المنصة.", "defaults": [["أرضيات الفينيل", "", "", "تنظيف بمنظف متعادل، بلا شمع", ""], ["حماية الجدران والزوايا", "", "", "", ""], ["الأسقف المعلقة", "", "", "استبدال البلاطة المتضررة بنفس الرمز", ""], ["الأبواب والأقفال", "", "", "", ""], ["الكاونترات والأسطح", "", "", "", ""], ["الستائر المضادة للبكتيريا", "", "", "تُغسل أو تُستبدل بحسب سياسة مكافحة العدوى", ""], ["اللوحات والإرشاد", "", "", "لا ملصقات عليها", ""]]}, {"key": "spares", "title": "قطع الغيار والأدوات المسلَّمة", "rows": "spares", "cols": [["item", "القطعة / الأداة"], ["qty", "الكمية"], ["for", "للنظام"], ["where", "مكان التخزين"]], "body": "ما سلّمه المقاول من قطع غيار ومفاتيح وأدوات، ويُضم إلى المخزون الاحتياطي للأنظمة الحرجة (M-05)."}, {"key": "docs", "title": "الوثائق المرجعية", "auto": "docs", "body": "المخططات كما نُفذت وكتيبات التشغيل والصيانة وشهادات الاختبار محفوظة في مستندات المشروع ومخططاته على المنصة، وهذه قائمتها. النسخة المعتمدة هي آخر إصدار في المنصة."}, {"key": "safety", "title": "السلامة والطوارئ", "body": "## أنظمة الحريق\n- لا يُعطَّل أي جزء من أنظمة الحريق إلا بسجل تعطيل وإجراءات سلامة بديلة (H-01، R-14).\n- مخارج الطوارئ وممراتها خالية دائماً، وأبواب الحريق لا تُثبت مفتوحة.\n## الطوارئ في المرافق\n- انقطاع الكهرباء: التحقق من إقلاع المولد خلال ثوانٍ، وأولوية المناطق الحرجة.\n- انقطاع الغازات الطبية أو إنذارها: إبلاغ فوري للتمريض في المنطقة والتحويل للأسطوانات.\n- تسرب مياه: الإغلاق من نقطة العزل في جدول الأنظمة، وحماية الأجهزة.\n- توقف مصعد بركاب: الاتصال بالركاب وطمأنتهم، واستدعاء فني المصاعد.\n- كل حدث يُسجَّل «بلاغ طارئ» ويُكتب تقريره خلال 48 ساعة (G-11، H-03).\n## الإخلاء\n- مخططات الإخلاء معلقة في كل طابق، والتمارين لكل وردية كل ربع سنة (H-02، K-11).\n> الخطط المرجعية: خطة السلامة من الحريق (PL-04)، وخطة إدارة الطوارئ (PL-07)."}, {"key": "procs", "title": "الإجراءات المرتبطة", "auto": "procs", "procs": "G-04 · F-03 · G-05 · G-06 · M-01 · M-02 · M-03 · M-05 · H-01 · H-02 · G-11 · F-01 · G-12 · P-14", "body": "الإجراءات المعتمدة في الحوكمة التي تحكم تشغيل هذه المنشأة. كل إجراء يفتح بخطواته ومسؤولياته."}, {"key": "log", "title": "سجل الإصدارات", "auto": "log", "body": "كل إصدار من الدليل بتاريخه ومن اعتمده."}]'::jsonb) on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections) values ('user','دليل مستخدمي المنشأة','الكادر الطبي والإداري في المنشأة ومديرها','[{"key": "welcome", "title": "مرحباً بكم في منشأتكم", "auto": "project", "body": "هذا الدليل لكم أنتم: الأطباء والتمريض والإداريون في {facility}. صُممت المنشأة حول المريض وحولكم، وهذا الدليل يشرح كيف تستخدمونها وكيف تحافظون عليها، ومن تتصلون به عند أي حاجة.\n- اقرؤوه مرة كاملة، واحتفظوا بالنسخة المطبوعة في مكتب مدير المنشأة وغرفة التمريض.\n- أي سؤال لا تجدون إجابته هنا: اسألوا المرافق."}, {"key": "report", "title": "كيف أبلّغ عن عطل أو أطلب خدمة", "body": "## البلاغ العادي\n- من «مركز البلاغات» في المنصة: اختر نوع الطلب، واكتب رمز الغرفة المثبت على لوحتها (R-16)، وأرفق صورة إن أمكن.\n- يصلك رقم البلاغ، وتتابع حالته حتى الإغلاق، ثم تقيّم الخدمة.\n- الأولوية بحسب أثر العطل على المرضى، لا بحسب من رفعه (R-17).\n## الطوارئ\n- تسرب مياه، انقطاع كهرباء أو غاز طبي، دخان، توقف مصعد بركاب: اتصلوا بالصيانة فوراً على الرقم في صفحة «أرقام مهمة»، ثم يُسجَّل البلاغ (R-09).\n! لا تحاولوا إصلاح أي عطل بأنفسكم، ولا تفتحوا لوحات الكهرباء أو الأسقف."}, {"key": "contacts", "title": "أرقام مهمة", "rows": "contacts", "cols": [["role", "لمن"], ["name", "الاسم"], ["phone", "الهاتف"], ["note", "متى"]], "body": "اطبعوا هذه الصفحة وعلّقوها في غرفة التمريض والاستقبال.", "defaults": [["الصيانة — طوارئ", "", "", "تسرب، انقطاع، عطل يهدد المرضى"], ["الأمن والسلامة", "", "", "حريق، دخان، حادث، شخص عنيف"], ["المرافق", "", "", "إغلاق غرفة، نقل أثاث، تعديل"], ["تقنية المعلومات", "", "", "الشبكة، الأجهزة، الأنظمة"], ["الصيانة الطبية", "", "", "عطل جهاز طبي"], ["الخدمات العامة", "", "", "النظافة، النفايات، الحشرات"]]}, {"key": "rooms", "title": "غرف المنشأة ورموزها", "auto": "rooms_brief", "body": "لكل غرفة رمز على لوحتها. استخدموا الرمز في كل بلاغ وطلب؛ فهو يوصل الفني إلى المكان الصحيح ويحفظ تاريخ الغرفة."}, {"key": "use", "title": "استخدام الفراغات والأنظمة", "body": "## التكييف\n- اتركوا منظم الحرارة على الإعداد المحدد؛ التعديل الكبير يرهق النظام ولا يبرّد أسرع.\n- لا تغطوا فتحات التكييف ولا تضعوا عليها أوراقاً أو أثاثاً.\n- الغرف ذات الضغط الخاص (العزل، التعقيم): أبقوا أبوابها مغلقة.\n## الكهرباء\n- لا توصيلات متعددة متسلسلة، ولا سخانات أو أجهزة شخصية غير معتمدة.\n- مقابس الطوارئ (اللون المميز) للأجهزة الطبية الحرجة فقط.\n## المياه والمغاسل\n- مغاسل غسل الأيدي لغسل الأيدي فقط؛ لا تُصب فيها سوائل أو بقايا.\n- أبلغوا فوراً عن أي تسرب أو ضعف في الضغط.\n## الأبواب والجدران\n- لا تُثقب الجدران ولا يُعلّق عليها شيء إلا بطلب؛ حماية الجدران جزء من التصميم.\n- أبواب الحريق تبقى مغلقة ولا تُسند بأي شيء.\n## الأثاث والتجهيزات\n- الأثاث معتمد ومرتب لخدمة سير العمل؛ النقل أو التغيير بطلب عبر المنصة (S-04).\n- الأجهزة الطبية الجديدة لا تُركب إلا بعد تجهيز موقعها واستلامها (G-07، R-03).\n## الهوية واللوحات\n- لا ملصقات أو أوراق على اللوحات والواجهات والأبواب الزجاجية؛ الإعلانات في الأماكن المخصصة لها."}, {"key": "clean", "title": "النظافة والنفايات", "body": "- النفايات تُفرز من مصدرها في الحاوية الصحيحة؛ الخلط يعرّض الجميع للخطر (R-31، S-02).\n- الأدوات الحادة في حاويات الحادة فقط، ولا تُملأ فوق الخط.\n- أي ملاحظة على النظافة تُسجل بلاغاً للخدمات العامة، وتُقاس جودة النظافة بالتفتيش (R-32).\n- الانسكابات الكيميائية: أبعدوا الناس، واستخدموا طقم الانسكاب، وأبلغوا الأمن والسلامة (H-04)."}, {"key": "fire", "title": "السلامة من الحريق", "body": "## إذا رأيت حريقاً أو دخاناً\n- أنقذ من في الخطر المباشر.\n- أطلق الإنذار من أقرب كاسر زجاج، واتصل بالأمن والسلامة.\n- احصر الحريق بإغلاق الأبواب.\n- أطفئ إن كان صغيراً وآمناً، أو أخلِ المكان.\n## الطفاية\n- اسحب مسمار الأمان، وجّه الفوهة إلى قاعدة اللهب، اضغط المقبض، وحرّكها يميناً ويساراً.\n## الإخلاء\n- اعرف أقرب مخرجين لمكان عملك من مخطط الإخلاء المعلق.\n- لا تستخدم المصاعد أثناء الحريق.\n- الإخلاء الأفقي أولاً إلى منطقة حريق مجاورة، ثم الرأسي عند الطلب (H-02).\n! لا تضع أي شيء في ممرات الخروج ولا أمام طفايات وصناديق الحريق."}, {"key": "emerg", "title": "ماذا أفعل عند…", "body": "## انقطاع الكهرباء\n- المولد يعيد التغذية للأحمال الأساسية خلال ثوانٍ. تأكدوا أن الأجهزة الحرجة على مقابس الطوارئ، وأبلغوا الصيانة.\n## إنذار الغازات الطبية\n- أبلغوا الصيانة فوراً، وجهزوا أسطوانات الأكسجين للمرضى المعتمدين عليه.\n## تسرب مياه\n- أبعدوا الأجهزة والملفات، وأبلغوا الصيانة، ولا تلمسوا المقابس القريبة من الماء.\n## توقف مصعد\n- اضغط زر الاتصال داخل المصعد وانتظر؛ لا تحاول الخروج بنفسك.\n## حادث أو إصابة أثناء العمل\n- أسعف، ثم أبلغ الأمن والسلامة؛ كل حادث أو شبه حادث يُبلَّغ (R-19، H-03)."}, {"key": "approve", "title": "ما يحتاج موافقة قبل تنفيذه", "body": "حتى تبقى المنشأة آمنة وعلى معيارها، هذه الأمور لا تُنفذ إلا بطلب عبر المنصة وموافقة الجهة المختصة:\n- أي تعديل في الغرف أو الجدران أو الأبواب، أو تغيير استخدام غرفة (G-12).\n- تركيب جهاز طبي أو تقني جديد (G-07، T-03).\n- نقل أثاث أو إضافة قطع جديدة (S-04).\n- إغلاق غرفة أو عيادة لأي سبب (F-01).\n- دخول أي مقاول أو عامل للعمل داخل المنشأة؛ لا دخول بلا تهيئة وبطاقة وتصريح (R-21، M-01)."}, {"key": "warranty", "title": "المنشأة في فترة الضمان", "body": "المنشأة في فترة ضمان المقاول حتى {warranty}. كل عيب يُبلَّغ عنه مبكراً يُصلحه المقاول على حسابه؛ والعيب الذي يُسكت عنه يصبح تكلفة على التجمع بعد انتهاء الضمان.\n- أبلغوا عن أي تشقق أو تسرب أو عيب في التشطيبات أو الأبواب أو الأنظمة، مهما بدا بسيطاً."}, {"key": "rules", "title": "باختصار: افعل ولا تفعل", "body": "## افعل\n- أبلغ عبر المنصة برمز الغرفة.\n- أبقِ المخارج وأبواب الحريق خالية ومغلقة.\n- افرز النفايات من مصدرها.\n- اطلب قبل أي تعديل أو نقل أو تركيب.\n## لا تفعل\n- لا تصلح عطلاً بنفسك ولا تفتح اللوحات.\n- لا تثقب الجدران ولا تلصق على اللوحات.\n- لا تستخدم أجهزة كهربائية شخصية غير معتمدة.\n- لا تُدخل عاملاً دون تصريح."}]'::jsonb) on conflict (code) do nothing;

-- الحوكمة: قاعدة R-42، وحد اعتماد A-30، ونشاط K-30، وبند في قائمة تحقق التسليم، وسجل في دليل G-04 — مرة واحدة
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values ('R-42','لا تسليم بلا دليل منشأة','التكامل','لا يكتمل تسليم أي مشروع للتشغيل حتى يصدر له دليلان من المنصة: دليل التشغيل والصيانة لفرق الإدارة، ودليل مستخدمي المنشأة لكادرها.',
  '["يُصدر قسم المشاريع الدليلين قبل الاستلام الابتدائي ويراجعهما المرافق والصيانة والأمن والسلامة", "يعتمد الدليل مدير الإدارة، ويُسلَّم دليل المستخدم لمدير المنشأة قبل التشغيل", "جداول المواقع والأصول والضمانات وخطط الصيانة تُسحب من المنصة ولا تُكتب يدوياً", "أي تعديل لاحق في المساحات أو الأنظمة يُحدَّث في الدليل بإصدار جديد (G-12)", "مراجعة سنوية لكل دليل (K-30)"]'::jsonb,'PRJ','G-04','',42) on conflict (code) do nothing;
do $$ begin
  if not exists (select 1 from public.seed_marks where key = 'manuals_v1') then
    insert into public.gov_frame(code,kind,title,grp,sort,data) values ('A-30','auth','اعتماد دليل المنشأة (التشغيل والصيانة، والمستخدمين)','التشغيل والصيانة والسلامة',120,
      '{"propose":["PRJ"],"review":["FAC","MNT","SAF"],"approve":["DIR"],"limit":"قبل الاستلام الابتدائي، ومع كل تعديل جوهري (R-42)","ref":"G-04 · R-42"}'::jsonb) on conflict (code) do nothing;
    insert into public.gov_frame(code,kind,title,grp,sort,data) values ('K-30','cal','مراجعة أدلة المنشآت وتحديثها','التخطيط والحوكمة',121,
      '{"freq":"سنوي","months":[11],"owner":"FAC","ref":"R-42 · G-12","note":"كل منشأة سُلّمت بدليل: مطابقة الجداول والأنظمة وجهات الاتصال"}'::jsonb) on conflict (code) do nothing;
    update public.ops_kinds set checklist = checklist || '[{"k":"manual","l":"إصدار دليل التشغيل والصيانة ودليل مستخدمي المنشأة واعتمادهما (R-42)"}]'::jsonb
      where code = 'handover' and not checklist::text like '%"manual"%';
    update public.gov_processes set doc = jsonb_set(doc, '{records}', coalesce(doc->'records','[]'::jsonb) || '[{"name":"دليل التشغيل والصيانة ودليل مستخدمي المنشأة (R-42)","where":"أدلة المنشآت في المنصة","keep":"عمر المبنى"}]'::jsonb)
      where code = 'G-04' and doc <> '{}'::jsonb and not doc::text like '%دليل مستخدمي المنشأة%';
    insert into public.seed_marks(key) values ('manuals_v1');
  end if;
end $$;
